insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021000','Fluxo de materiais · verifique o conceito','O que é fluxo de materiais?','["Caminho entre recebimento, armazenamento e envio","Somente o nome do fornecedor","Apenas o preço de venda"]'::jsonb,'Caminho entre recebimento, armazenamento e envio. Fornecedor é quem fornece insumos ou produtos. O estoque guarda os materiais; a distribuição os leva ao destino. Um registro de entrada informa o que chegou, e um de saída informa o que deixou o estoque.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021000',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021001','Fluxo de materiais · verifique o conceito','Quem fornece os produtos?','["Cliente final em todos os casos","Fornecedor","Etiqueta do pedido"]'::jsonb,'Fornecedor. Exemplo: chegam 20 caixas de cadernos do fornecedor. A equipe confere as caixas, registra a entrada e guarda no local indicado. Quando 7 caixas saem para uma escola, o saldo passa a 20 − 7 = 13 caixas.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021001',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021002','Fluxo de materiais · verifique o conceito','Chegaram 20 caixas e saíram 7. Qual é o saldo?','["27 caixas","7 caixas","13 caixas"]'::jsonb,'13 caixas. A sequência deve permitir conferir o caminho: receber e conferir, registrar a entrada, armazenar, separar o pedido, conferir e enviar. Registre as quantidades na mesma unidade; 20 caixas não significam 20 cadernos.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021002',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021003','Fluxo de materiais · verifique o conceito','Chegaram 19 das 20 caixas esperadas. O que fazer?','["Registrar a divergência e conferir o documento","Registrar 20 sem conferir","Enviar tudo sem contar"]'::jsonb,'Registrar a divergência e conferir o documento. Limite: um registro não prova que o material físico está correto. Se chegarem 19 caixas em vez das 20 esperadas, registre a divergência e confira com o documento antes de prometer a entrega. Distribuir não elimina atrasos e avarias.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021003',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021004','Controle de estoque · verifique o conceito','Que dados permitem conferir uma movimentação?','["Somente a cor da embalagem","Produto, quantidade, unidade, data e documento","Somente o preço total"]'::jsonb,'Produto, quantidade, unidade, data e documento. Saldo inicial é a quantidade no começo do período. Some as entradas e subtraia as saídas para obter o saldo registrado. Fornecedor fornece insumos; estoque armazena produtos; distribuição entrega ao destino.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021004',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021005','Controle de estoque · verifique o conceito','Saldo 30, entrada 12 e saída 8: qual é o saldo?','["50 unidades","10 unidades","34 unidades"]'::jsonb,'34 unidades. Exemplo de um item: o saldo inicial é 30 unidades, entram 12 e saem 8. O saldo registrado é 30 + 12 − 8 = 34 unidades. A contagem física deve ser comparada às 34 registradas.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021005',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021006','Controle de estoque · verifique o conceito','O que é inventário?','["Contagem física dos materiais","Envio ao cliente","Compra de qualquer produto"]'::jsonb,'Contagem física dos materiais. Inventário é a contagem dos materiais existentes. Se a contagem mostrar 32 unidades, a diferença é 32 − 34 = −2 unidades. Procure entrada, saída ou avaria sem registro antes de corrigir o saldo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021006',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021007','Controle de estoque · verifique o conceito','Registro 34 e contagem 32: qual é a diferença física menos registrada?','["2 entradas confirmadas","−2 unidades","66 unidades"]'::jsonb,'−2 unidades. Limite: itens diferentes não formam um único saldo. Separe produtos, unidades e locais; não some caixas com peças sem conversão conhecida. Uma diferença precisa de investigação e registro, não de ajuste sem motivo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021007',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021008','Preparação de pedidos · verifique o conceito','O que comparar na conferência?','["Somente o peso da caixa","Somente a cor do pacote","Produto, código e quantidade com o pedido"]'::jsonb,'Produto, código e quantidade com o pedido. Separação é buscar no estoque os itens listados. Conferência é comparar produto, código e quantidade com o pedido. Embalagem protege o conteúdo; identificação relaciona o pacote ao destinatário e ao pedido.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021008',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021009','Preparação de pedidos · verifique o conceito','Pedido com 2 cadernos, 1 régua e 3 lápis tem quantas peças?','["6 peças","3 peças","5 peças"]'::jsonb,'6 peças. Exemplo: o pedido pede 2 cadernos, 1 régua e 3 lápis. Separe esses três tipos de produto e conte 6 peças no total. Confira cada linha: ter 6 peças não basta se uma régua foi trocada por um lápis.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021009',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021010','Preparação de pedidos · verifique o conceito','Se a régua estiver em falta, o que fazer?','["Trocar por lápis sem autorização","Sinalizar a falta e confirmar o procedimento","Registrar como enviada"]'::jsonb,'Sinalizar a falta e confirmar o procedimento. Após conferir, escolha proteção adequada, identifique o volume e registre a saída das quantidades efetivamente enviadas. Se faltar a régua, sinalize a falta e confirme o procedimento de envio parcial antes de fechar o pacote.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021010',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021011','Preparação de pedidos · verifique o conceito','Quando conferir o conteúdo?','["Somente após a entrega","Depois de descartar o pedido","Antes de lacrar a embalagem"]'::jsonb,'Antes de lacrar a embalagem. Limite: não substitua item por conta própria nem registre saída de algo que ficou no estoque. A conferência precisa ocorrer antes do lacre, quando ainda é possível corrigir uma quantidade ou um produto incorreto.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021011',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021012','Calcular estoque disponível · verifique o conceito','Uma reserva ainda está fisicamente no estoque?','["Sim, até a saída física","Nunca","Só depois da entrega"]'::jsonb,'Sim, até a saída física. Entrada aumenta o saldo físico; saída o reduz. Uma reserva compromete unidades que ainda estão fisicamente presentes. Uma avaria torna a unidade indisponível até que seja tratada; nesta atividade, reservas e avarias são grupos distintos.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021012',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021013','Calcular estoque disponível · verifique o conceito','120 + 80 − 135 resulta em qual saldo físico?','["30 unidades","65 unidades","335 unidades"]'::jsonb,'65 unidades. Exemplo: há 120 unidades, entram 80 e saem 135. O saldo físico é 120 + 80 − 135 = 65. Dessas 65, há 15 avariadas e 20 reservadas. O disponível é 65 − 15 − 20 = 30 unidades.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021013',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021014','Calcular estoque disponível · verifique o conceito','65 físicas, 15 avariadas e 20 reservadas distintas: disponível?','["65 unidades","100 unidades","30 unidades"]'::jsonb,'30 unidades. A conta completa é 120 + 80 − 135 − 15 − 20 = 30. Confira a decomposição: 30 disponíveis + 15 avariadas + 20 reservadas = 65 físicas. Uma reserva não é uma segunda saída física.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021014',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021015','Calcular estoque disponível · verifique o conceito','Por que verificar sobreposição entre avarias e reservas?','["Para não descontar a mesma unidade duas vezes","Para somar todas as reservas ao saldo","Para ignorar as avarias"]'::jsonb,'Para não descontar a mesma unidade duas vezes. Limite: não desconte a mesma unidade duas vezes. Se uma unidade reservada também estiver avariada, identifique a sobreposição antes da conta. Resultado negativo indica compromissos maiores que o saldo utilizável e exige revisão dos registros.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021015',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021016','Organizar a expedição · verifique o conceito','Qual etapa vem antes de embalar e lacrar?','["Ignorar o pedido","Conferir itens e quantidades","Apagar o saldo"]'::jsonb,'Conferir itens e quantidades. Cada etapa deixa uma evidência: lista de separação, confirmação dos itens, etiqueta do volume e registro de saída. A etiqueta associa o volume ao pedido e ao destinatário; não substitui a contagem do conteúdo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021016',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021017','Organizar a expedição · verifique o conceito','Para que serve a identificação do volume?','["Substituir a contagem dos itens","Aumentar o estoque físico","Relacionar volume, pedido e destinatário"]'::jsonb,'Relacionar volume, pedido e destinatário. Exemplo: um pedido contém 4 pastas e 2 cadernos. Separe os itens, confira cada quantidade, embale e identifique. Só então registre a saída de 4 pastas e 2 cadernos correspondentes ao envio preparado.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021017',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021018','Organizar a expedição · verifique o conceito','Foram pedidas 4 pastas e separadas 3. O que fazer?','["Interromper o fechamento e tratar a falta","Lacrar e registrar 4","Trocar o nome do destinatário"]'::jsonb,'Interromper o fechamento e tratar a falta. Se a conferência encontrar apenas 3 pastas, interrompa o fechamento, corrija ou registre a falta conforme o procedimento. Conferir antes de lacrar evita ter de reabrir um volume com conteúdo incorreto.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021018',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021019','Organizar a expedição · verifique o conceito','O registro da saída deve representar o quê?','["Tudo que estava previsto mesmo faltando","O pedido efetivamente preparado e enviado","O estoque anterior à separação"]'::jsonb,'O pedido efetivamente preparado e enviado. Limite: a sequência organizada reduz erros, mas não garante ausência de dano no transporte. Verifique proteção, destinatário e rastreabilidade. Não registre como enviado um pedido que ainda está aguardando correção.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000011',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021019',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021020','Células e organelas · verifique o conceito','O que delimita a célula e controla trocas com o meio?','["Flor","Fruto","Membrana"]'::jsonb,'Membrana. Organelas são estruturas internas com funções específicas. Mitocôndrias participam da respiração celular, processo que disponibiliza energia para a célula. Cloroplastos realizam fotossíntese em células vegetais fotossintetizantes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021020',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021021','Células e organelas · verifique o conceito','Onde fica a maior parte do material genético de uma célula eucariótica?','["Núcleo","Fora da célula","Somente na membrana"]'::jsonb,'Núcleo. Exemplo: em uma célula de folha exposta à luz, cloroplastos participam da produção de matéria orgânica pela fotossíntese. Essa célula também possui mitocôndrias; uma função não elimina a outra.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021021',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021022','Células e organelas · verifique o conceito','Qual organela realiza fotossíntese?','["Mitocôndria","Cloroplasto","Núcleo"]'::jsonb,'Cloroplasto. Compare estruturas e funções: membrana controla trocas com o meio; núcleo contém a maior parte do material genético na célula eucariótica; citoplasma abriga estruturas e reações. Uma célula animal possui mitocôndrias, mas não cloroplastos.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021022',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021023','Células e organelas · verifique o conceito','Uma célula animal geralmente possui qual organela?','["Cloroplasto","Parede vegetal","Mitocôndria"]'::jsonb,'Mitocôndria. Limite: o desenho didático simplifica formas e proporções. Nem toda célula tem núcleo delimitado: bactérias são procarióticas. Nem toda célula vegetal possui cloroplastos; células de muitas raízes não fazem fotossíntese.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021023',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021024','Células e organelas · verifique o conceito','Toda célula vegetal possui cloroplastos?','["Não, muitas células de raízes não possuem","Sim, sem exceção","Somente as células animais possuem"]'::jsonb,'Não, muitas células de raízes não possuem. Limite: o desenho didático simplifica formas e proporções. Nem toda célula tem núcleo delimitado: bactérias são procarióticas. Nem toda célula vegetal possui cloroplastos; células de muitas raízes não fazem fotossíntese.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021024',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021025','Grupos de plantas · verifique o conceito','Qual grupo não possui vasos condutores verdadeiros?','["Gimnospermas","Briófitas","Angiospermas"]'::jsonb,'Briófitas. Briófitas, como musgos, não possuem vasos condutores verdadeiros nem sementes. Pteridófitas, como samambaias, possuem vasos, mas não sementes. Esses dois grupos se reproduzem por ciclos que incluem esporos.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021025',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021026','Grupos de plantas · verifique o conceito','Samambaia tem vasos e não produz sementes. Qual grupo?','["Angiospermas","Gimnospermas","Pteridófitas"]'::jsonb,'Pteridófitas. Gimnospermas, como pinheiros, possuem sementes que não ficam dentro de frutos. Angiospermas produzem flores e frutos; o fruto envolve as sementes. Uma mangueira com flores e mangas é exemplo de angiosperma.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021026',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021027','Grupos de plantas · verifique o conceito','O que caracteriza as sementes das gimnospermas?','["Não ficam dentro de frutos","Sempre ficam em frutos","Não existem"]'::jsonb,'Não ficam dentro de frutos. Exemplo de comparação: musgo sem vasos verdadeiros é briófita; samambaia com vasos e sem sementes é pteridófita; pinheiro com sementes sem frutos é gimnosperma; feijoeiro com flores e vagens é angiosperma.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021027',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021028','Grupos de plantas · verifique o conceito','Uma planta está sem flor hoje. O que concluir?','["É obrigatoriamente briófita","Ainda faltam evidências para definir o grupo","Não pode ser angiosperma"]'::jsonb,'Ainda faltam evidências para definir o grupo. Limite: tamanho e cor não bastam para classificar. Uma angiosperma pode estar sem flores na época observada; ausência momentânea de flor não comprova outro grupo. Registre as características e o que ainda falta verificar.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021028',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021029','Observação científica · verifique o conceito','Qual frase é observação direta?','["A raiz oculta tem 10 cm","A planta nunca terá fruto","Vejo quatro folhas e uma flor"]'::jsonb,'Vejo quatro folhas e uma flor. Órgãos vegetais possuem funções: a raiz absorve água e sais e ajuda na fixação; o caule sustenta e transporta substâncias; a folha costuma ser o principal órgão fotossintetizante; a flor participa da reprodução das angiospermas.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021029',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021030','Observação científica · verifique o conceito','Qual é uma função da raiz?','["Absorver água e sais","Produzir flores em todos os casos","Substituir todas as folhas"]'::jsonb,'Absorver água e sais. Exemplo de registro: em uma planta no vaso, vejo caule, quatro folhas e uma flor. Não vejo a raiz porque está coberta. A frase ‘a raiz absorve água’ é uma explicação de função, não uma observação direta dessa raiz.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021030',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021031','Observação científica · verifique o conceito','A raiz não está visível no vaso. O que registrar?','["A planta não possui raiz","Raiz não visível, sem inventar medidas","Raiz obrigatoriamente vermelha"]'::jsonb,'Raiz não visível, sem inventar medidas. Anote data, local, partes visíveis e uma descrição sem arrancar a planta. Um desenho rotulado ou uma foto autorizada pode ajudar a repetir a observação. Se comparar dias, mantenha ponto de vista e condições semelhantes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021031',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021032','Identificar estruturas celulares · verifique o conceito','Qual número indica a membrana no esquema da prática?','["2","3","1"]'::jsonb,'1. A membrana delimita a célula e regula trocas. O núcleo abriga a maior parte do material genético. O citoplasma é a região interna entre a membrana e o núcleo, onde ficam diversas estruturas celulares.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021032',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021033','Identificar estruturas celulares · verifique o conceito','Qual número indica o citoplasma no esquema?','["3","2","1"]'::jsonb,'3. No esquema da prática, 1 indica a membrana, 2 indica o núcleo e 3 indica o citoplasma. Siga cada linha até a estrutura: o número 2 está à direita, mas sua linha termina na estrutura arredondada central.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021033',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021034','Identificar estruturas celulares · verifique o conceito','Que função corresponde ao núcleo eucariótico?','["Ser o limite externo da célula","Abrigar a maior parte do material genético","Ser uma flor"]'::jsonb,'Abrigar a maior parte do material genético. Exemplo: se a pergunta pede o núcleo, escolha 2 porque a linha aponta para a estrutura central delimitada. Se pede o contorno externo, escolha 1. A região ao redor do núcleo corresponde a 3, citoplasma.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021034',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021035','Identificar estruturas celulares · verifique o conceito','Como localizar uma estrutura numerada?','["Olhar apenas a posição do número","Usar sempre a mesma cor em qualquer desenho","Seguir a linha até a estrutura indicada"]'::jsonb,'Seguir a linha até a estrutura indicada. Limite: a posição do número no papel não é a posição da estrutura. Cores e proporções são escolhas didáticas; não representam todas as células nem todas as organelas. Use a ponta da linha e a função para conferir.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021035',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021036','Classificar grupos de plantas · verifique o conceito','Qual característica separa gimnospermas de angiospermas neste estudo?','["Sementes sem frutos ou sementes dentro de frutos","Somente a altura","Somente a presença de vasos"]'::jsonb,'Sementes sem frutos ou sementes dentro de frutos. Briófitas não possuem vasos condutores verdadeiros. Pteridófitas possuem vasos, mas não sementes. Gimnospermas têm sementes sem frutos. Angiospermas possuem flores e frutos que envolvem sementes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021036',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021037','Classificar grupos de plantas · verifique o conceito','Uma planta com vasos e sem sementes pertence a qual grupo estudado?','["Briófitas","Pteridófitas","Gimnospermas"]'::jsonb,'Pteridófitas. Exemplo: a amostra A tem sementes em cones, sem frutos, e corresponde a uma gimnosperma. A amostra B tem flores e frutos com sementes, correspondendo a uma angiosperma. Vasos, sozinhos, não distinguem esses dois grupos.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021037',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021038','Classificar grupos de plantas · verifique o conceito','Amostra com sementes em cones, sem frutos: qual grupo?','["Briófitas","Angiospermas","Gimnospermas"]'::jsonb,'Gimnospermas. Organize uma decisão: sem vasos verdadeiros, considere briófitas; com vasos e sem sementes, pteridófitas; com sementes, investigue frutos. Confira mais de uma característica e registre qual evidência sustenta cada associação.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021038',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021039','Classificar grupos de plantas · verifique o conceito','Uma amostra incompleta não mostra fruto nem semente. O que fazer?','["Registrar dados insuficientes e buscar mais evidências","Classificar só pela cor","Afirmar que não produz sementes"]'::jsonb,'Registrar dados insuficientes e buscar mais evidências. Limite: uma amostra incompleta pode não mostrar semente ou fruto existente em outra época. Escreva ‘dados insuficientes’ quando necessário. Não transforme a falta de uma observação em prova de ausência no grupo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000012',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021039',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021040','Grandezas e unidades · verifique o conceito','Qual registro representa um comprimento?','["2 s","2 m","2 kg"]'::jsonb,'2 m. No Sistema Internacional, comprimento usa metro (m), tempo usa segundo (s) e massa usa quilograma (kg). Massa expressa uma propriedade do corpo; peso é a força gravitacional sobre ele, medida em newtons (N).','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021040',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021041','Grandezas e unidades · verifique o conceito','Qual unidade do SI mede tempo?','["Quilograma (kg)","Newton (N)","Segundo (s)"]'::jsonb,'Segundo (s). Força descreve uma interação capaz de alterar o movimento ou deformar um corpo e usa newton (N). Energia está associada à capacidade de realizar trabalho ou provocar transformações e usa joule (J). Potência é a energia transferida por tempo e usa watt (W).','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021041',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021042','Grandezas e unidades · verifique o conceito','Qual é a diferença entre massa e peso?','["Massa usa kg; peso é força e usa N","Ambos são sempre medidos em J","Peso é comprimento e usa m"]'::jsonb,'Massa usa kg; peso é força e usa N. Exemplo: registre comprimento de uma mesa como 2 m, duração como 10 s, massa de um pacote como 3 kg, força como 20 N, energia como 100 J e potência como 5 W. Cada unidade identifica uma grandeza diferente.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021042',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021043','Movimento · verifique o conceito','O que caracteriza movimento em relação a um referencial?','["Somente a massa do corpo","Mudança de posição","Somente a cor do objeto"]'::jsonb,'Mudança de posição. Rapidez média é a distância total dividida pelo tempo total: rapidez = distância / tempo. A unidade m/s significa quantos metros por segundo correspondem à média do trajeto, sem afirmar que o ritmo foi constante.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021043',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021044','Movimento · verifique o conceito','Como calcular rapidez média?','["Tempo dividido pela distância","Distância somada ao tempo","Distância total dividida pelo tempo total"]'::jsonb,'Distância total dividida pelo tempo total. Exemplo: uma pessoa caminha 10 m em 5 s. Dividindo 10 por 5, a rapidez média é 2 m/s. Se percorrer os mesmos 10 m em 10 s, a média será 1 m/s, menor porque levou mais tempo.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021044',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021045','Movimento · verifique o conceito','10 m em 5 s corresponde a qual rapidez média?','["2 m/s","50 m/s","0,5 m/s"]'::jsonb,'2 m/s. Distância e deslocamento são diferentes: ao andar 5 m e voltar 5 m ao início, a distância é 10 m e o deslocamento total é zero. A velocidade média usa deslocamento e direção; a rapidez média usa distância.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021045',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021046','Movimento · verifique o conceito','Andar 5 m e voltar 5 m ao início dá qual distância total?','["0 m","10 m","5 m"]'::jsonb,'10 m. Limite: tempo total precisa ser maior que zero para dividir. Inclua uma parada se ela pertence ao intervalo observado. Uma média de 2 m/s não permite concluir que a pessoa manteve 2 m/s a cada instante.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021046',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021047','Movimento · verifique o conceito','É válido dividir a distância por tempo total zero?','["Sim, o resultado sempre é zero","Sim, basta retirar a unidade","Não, a divisão por zero não é definida"]'::jsonb,'Não, a divisão por zero não é definida. Limite: tempo total precisa ser maior que zero para dividir. Inclua uma parada se ela pertence ao intervalo observado. Uma média de 2 m/s não permite concluir que a pessoa manteve 2 m/s a cada instante.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021047',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021048','Medição e análise · verifique o conceito','Que dados permitem calcular rapidez média?','["Distância e tempo com unidades","Massa e cor do tênis","Somente o tempo"]'::jsonb,'Distância e tempo com unidades. Uma fita métrica pode medir distância; um cronômetro registra duração. Anote valor e unidade de cada leitura. Rapidez média usa distância por tempo; velocidade média usa deslocamento por tempo e exige considerar direção.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021048',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021049','Medição e análise · verifique o conceito','12 m percorridos em 6 s dão qual rapidez média?','["72 m/s","2 m/s","0,5 m/s"]'::jsonb,'2 m/s. Exemplo em linha reta sem retorno: entre duas marcas há 12 m e o tempo é 6 s. A rapidez média é 12 / 6 = 2 m/s. Nesse percurso, a distância e o módulo do deslocamento coincidem.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021049',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021050','Medição e análise · verifique o conceito','Duas medições dão tempos ligeiramente diferentes. O que registrar?','["Somente a leitura preferida","Um tempo inventado sem variação","As leituras e as condições de medição"]'::jsonb,'As leituras e as condições de medição. Planeje medições repetidas do mesmo trecho, mantendo o critério. Tempos de 6,0 s e 6,2 s podem diferir por reação ao cronômetro ou variação de movimento; registre as duas leituras em vez de apagar a que não esperava.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021050',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021051','Medição e análise · verifique o conceito','Que situação permite distância e módulo do deslocamento iguais?','["Trecho em linha reta sem retorno","Ida e volta ao mesmo ponto","Qualquer trajeto com curvas e retorno"]'::jsonb,'Trecho em linha reta sem retorno. Limite: um cálculo não elimina incerteza de medição. Escolha um trajeto seguro para caminhada ou trabalhe com dados hipotéticos. Não faça teste em via com tráfego; não conclua a precisão do instrumento apenas pelo número de casas decimais anotado.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021051',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021052','Calcular rapidez média · verifique o conceito','Como combinar duas etapas para obter rapidez média?','["Somar somente as rapidez das etapas","Somar distâncias e tempos antes de dividir","Ignorar a etapa mais lenta"]'::jsonb,'Somar distâncias e tempos antes de dividir. Em um trajeto por etapas, some primeiro todas as distâncias e todos os tempos. Inclua intervalos de parada que façam parte da observação. Só depois divida a distância total pelo tempo total, com unidades compatíveis.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021052',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021053','Calcular rapidez média · verifique o conceito','120 m + 60 m e 60 s + 30 s resultam em quê?','["180 m em 30 s","60 m em 90 s","180 m em 90 s"]'::jsonb,'180 m em 90 s. Exemplo: uma pessoa percorre 120 m em 60 s e mais 60 m em 30 s. A distância total é 120 + 60 = 180 m e o tempo total é 60 + 30 = 90 s. Logo, 180 m / 90 s = 2 m/s.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021053',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021054','Calcular rapidez média · verifique o conceito','100 m em 40 s dão qual rapidez média?','["2,5 m/s","2 m/s","4 m/s"]'::jsonb,'2,5 m/s. Confira com outra situação: 10 m em 10 s e 90 m em 30 s totalizam 100 m em 40 s, ou 2,5 m/s. Fazer a média simples de 1 m/s e 3 m/s daria 2 m/s e estaria errado, pois as durações são diferentes.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021054',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021055','Calcular rapidez média · verifique o conceito','Uma parada de 10 s dentro da observação entra na conta?','["Não, tempo parado nunca conta","Sim, no tempo total","Sim, como distância extra"]'::jsonb,'Sim, no tempo total. Limite: não divida por tempo zero nem some metros com quilômetros sem converter. Se a pessoa retorna ao ponto inicial, o deslocamento é zero, mas a distância e a rapidez podem ser positivas. A média não comprova ritmo constante.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021055',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021056','Interpretar uma medição · verifique o conceito','Quanto vale 0,12 km em metros?','["12 m","1200 m","120 m"]'::jsonb,'120 m. Um quilômetro corresponde a 1000 metros. Para passar de km para m, multiplique por 1000; para passar de m para km, divida por 1000. Um minuto corresponde a 60 segundos, portanto a conversão de tempo usa outro fator.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021056',2,'2'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021057','Interpretar uma medição · verifique o conceito','Quantos segundos há em 1 minuto?','["60 s","100 s","1000 s"]'::jsonb,'60 s. Exemplo: 1,5 km × 1000 = 1500 m. Os registros 1,5 km e 1500 m representam a mesma distância. Para comparar com 1200 m, use a mesma unidade: 1500 m é 300 m maior que 1200 m.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021057',0,'0'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021058','Interpretar uma medição · verifique o conceito','Qual a diferença entre 1500 m e 1200 m?','["0,3 m","300 m","2700 m"]'::jsonb,'300 m. Antes de calcular rapidez, converta também o tempo: 0,12 km são 120 m e 1 min são 60 s. Assim, 120 m / 60 s = 2 m/s. Registre as conversões para outra pessoa poder conferir a conta.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021058',1,'1'::jsonb) on conflict(question_id) do nothing;
insert into public.questions(id,title,prompt,options,explanation,kind,activity_type,category,subject_id,xp) values('00000000-0000-4000-8000-000000021059','Interpretar uma medição · verifique o conceito','Escrever 1500 m em lugar de 1,5 km comprova maior precisão?','["Sim, porque há mais algarismos","Sim, porque metros sempre são exatos","Não, é preciso conhecer instrumento e procedimento"]'::jsonb,'Não, é preciso conhecer instrumento e procedimento. Limite: escrever 1500 m em vez de 1,5 km não comprova maior precisão. Precisão depende do instrumento, do procedimento e da repetição; a escrita sozinha não basta. Não compare distância com tempo como se fossem a mesma grandeza.','choice','multiple_choice','Prática guiada','00000000-0000-4000-8000-000000000013',40) on conflict(id) do nothing;
insert into private.question_answers(question_id,correct_index,expected) values('00000000-0000-4000-8000-000000021059',2,'2'::jsonb) on conflict(question_id) do nothing;
update public.questions set explanation='Confira cada produto e quantidade antes de embalar. Identifique o pedido e registre a saída somente do que foi efetivamente enviado.' where id='00000000-0000-4000-8000-000000008014';
update public.questions set title='Grupos de plantas · prática',explanation='Angiospermas produzem flores e frutos. A ausência de flores em uma observação isolada não exclui esse grupo.' where id='00000000-0000-4000-8000-000000008018';
update public.questions set title='Observação científica · órgãos vegetais',explanation='A raiz absorve água e sais; a folha costuma ser o principal órgão fotossintetizante; a flor participa da reprodução das angiospermas.' where id='00000000-0000-4000-8000-000000008019';
update public.questions set explanation='Registre apenas as partes visíveis, sem arrancar a planta. Separe a descrição observada da explicação sobre a função de cada órgão.' where id='00000000-0000-4000-8000-000000008020';
update public.questions set title='Grandezas e unidades · associação',explanation='Força é medida em newtons (N), energia em joules (J) e potência em watts (W). São grandezas distintas.' where id='00000000-0000-4000-8000-000000008022';
update public.questions set explanation='Em um trecho reto sem retorno, a distância coincide com o módulo do deslocamento. Registre distância em metros e tempo em segundos; a rapidez média é distância dividida pelo tempo. Fora desse caso, diferencie rapidez de velocidade média.' where id='00000000-0000-4000-8000-000000008023';
update public.questions set title='Calcular rapidez média' where id='00000000-0000-4000-8000-000000012017';
update public.modules set title='Fluxo de materiais',body='Logística organiza o caminho dos materiais, desde o fornecedor até o destino. Fluxo de materiais é a sequência de recebimento, armazenamento, separação e envio; cada etapa precisa de informação sobre produto e quantidade.

Fornecedor é quem fornece insumos ou produtos. O estoque guarda os materiais; a distribuição os leva ao destino. Um registro de entrada informa o que chegou, e um de saída informa o que deixou o estoque.

Exemplo: chegam 20 caixas de cadernos do fornecedor. A equipe confere as caixas, registra a entrada e guarda no local indicado. Quando 7 caixas saem para uma escola, o saldo passa a 20 − 7 = 13 caixas.

A sequência deve permitir conferir o caminho: receber e conferir, registrar a entrada, armazenar, separar o pedido, conferir e enviar. Registre as quantidades na mesma unidade; 20 caixas não significam 20 cadernos.

Limite: um registro não prova que o material físico está correto. Se chegarem 19 caixas em vez das 20 esperadas, registre a divergência e confira com o documento antes de prometer a entrega. Distribuir não elimina atrasos e avarias.',question_id='00000000-0000-4000-8000-000000021000' where id='00000000-0000-4000-8000-000000003040';
update public.modules set title='Controle de estoque',body='Controle de estoque é o registro das entradas, saídas e saldos de cada item. Identifique produto, quantidade, unidade, data e documento para conseguir conferir cada movimentação depois.

Saldo inicial é a quantidade no começo do período. Some as entradas e subtraia as saídas para obter o saldo registrado. Fornecedor fornece insumos; estoque armazena produtos; distribuição entrega ao destino.

Exemplo de um item: o saldo inicial é 30 unidades, entram 12 e saem 8. O saldo registrado é 30 + 12 − 8 = 34 unidades. A contagem física deve ser comparada às 34 registradas.

Inventário é a contagem dos materiais existentes. Se a contagem mostrar 32 unidades, a diferença é 32 − 34 = −2 unidades. Procure entrada, saída ou avaria sem registro antes de corrigir o saldo.

Limite: itens diferentes não formam um único saldo. Separe produtos, unidades e locais; não some caixas com peças sem conversão conhecida. Uma diferença precisa de investigação e registro, não de ajuste sem motivo.',question_id='00000000-0000-4000-8000-000000021004' where id='00000000-0000-4000-8000-000000003041';
update public.modules set title='Preparação de pedidos',body='Um pedido informa quais produtos e quantidades devem chegar a um destinatário. Preparar o pedido é separar os itens certos, conferir, proteger na embalagem e registrar a saída.

Separação é buscar no estoque os itens listados. Conferência é comparar produto, código e quantidade com o pedido. Embalagem protege o conteúdo; identificação relaciona o pacote ao destinatário e ao pedido.

Exemplo: o pedido pede 2 cadernos, 1 régua e 3 lápis. Separe esses três tipos de produto e conte 6 peças no total. Confira cada linha: ter 6 peças não basta se uma régua foi trocada por um lápis.

Após conferir, escolha proteção adequada, identifique o volume e registre a saída das quantidades efetivamente enviadas. Se faltar a régua, sinalize a falta e confirme o procedimento de envio parcial antes de fechar o pacote.

Limite: não substitua item por conta própria nem registre saída de algo que ficou no estoque. A conferência precisa ocorrer antes do lacre, quando ainda é possível corrigir uma quantidade ou um produto incorreto.',question_id='00000000-0000-4000-8000-000000021008' where id='00000000-0000-4000-8000-000000003042';
update public.modules set title='Calcular estoque disponível',body='Saldo físico é a quantidade existente no estoque. Estoque disponível é a parte que pode atender novas vendas: retire do saldo físico as unidades avariadas e as reservadas para outros pedidos.

Entrada aumenta o saldo físico; saída o reduz. Uma reserva compromete unidades que ainda estão fisicamente presentes. Uma avaria torna a unidade indisponível até que seja tratada; nesta atividade, reservas e avarias são grupos distintos.

Exemplo: há 120 unidades, entram 80 e saem 135. O saldo físico é 120 + 80 − 135 = 65. Dessas 65, há 15 avariadas e 20 reservadas. O disponível é 65 − 15 − 20 = 30 unidades.

A conta completa é 120 + 80 − 135 − 15 − 20 = 30. Confira a decomposição: 30 disponíveis + 15 avariadas + 20 reservadas = 65 físicas. Uma reserva não é uma segunda saída física.

Limite: não desconte a mesma unidade duas vezes. Se uma unidade reservada também estiver avariada, identifique a sobreposição antes da conta. Resultado negativo indica compromissos maiores que o saldo utilizável e exige revisão dos registros.',question_id='00000000-0000-4000-8000-000000021012' where id='00000000-0000-4000-8000-000000004011';
update public.modules set title='Organizar a expedição',body='Expedição é a preparação e liberação dos pedidos para transporte. Ela reúne separação, conferência, embalagem, identificação e registro da saída para que o material enviado corresponda ao pedido.

Cada etapa deixa uma evidência: lista de separação, confirmação dos itens, etiqueta do volume e registro de saída. A etiqueta associa o volume ao pedido e ao destinatário; não substitui a contagem do conteúdo.

Exemplo: um pedido contém 4 pastas e 2 cadernos. Separe os itens, confira cada quantidade, embale e identifique. Só então registre a saída de 4 pastas e 2 cadernos correspondentes ao envio preparado.

Se a conferência encontrar apenas 3 pastas, interrompa o fechamento, corrija ou registre a falta conforme o procedimento. Conferir antes de lacrar evita ter de reabrir um volume com conteúdo incorreto.

Limite: a sequência organizada reduz erros, mas não garante ausência de dano no transporte. Verifique proteção, destinatário e rastreabilidade. Não registre como enviado um pedido que ainda está aguardando correção.',question_id='00000000-0000-4000-8000-000000021016' where id='00000000-0000-4000-8000-000000004012';
update public.modules set title='Células e organelas',body='Célula é uma unidade básica dos seres vivos. A membrana delimita a célula, o citoplasma ocupa a região interna e, nas células eucarióticas, o núcleo abriga a maior parte do material genético.

Organelas são estruturas internas com funções específicas. Mitocôndrias participam da respiração celular, processo que disponibiliza energia para a célula. Cloroplastos realizam fotossíntese em células vegetais fotossintetizantes.

Exemplo: em uma célula de folha exposta à luz, cloroplastos participam da produção de matéria orgânica pela fotossíntese. Essa célula também possui mitocôndrias; uma função não elimina a outra.

Compare estruturas e funções: membrana controla trocas com o meio; núcleo contém a maior parte do material genético na célula eucariótica; citoplasma abriga estruturas e reações. Uma célula animal possui mitocôndrias, mas não cloroplastos.

Limite: o desenho didático simplifica formas e proporções. Nem toda célula tem núcleo delimitado: bactérias são procarióticas. Nem toda célula vegetal possui cloroplastos; células de muitas raízes não fazem fotossíntese.',question_id='00000000-0000-4000-8000-000000021020' where id='00000000-0000-4000-8000-000000003060';
update public.modules set title='Grupos de plantas',body='Classificar plantas é comparar características compartilhadas. Vasos condutores transportam água e outras substâncias; sementes protegem o embrião. Flores e frutos ajudam a reconhecer um grupo específico.

Briófitas, como musgos, não possuem vasos condutores verdadeiros nem sementes. Pteridófitas, como samambaias, possuem vasos, mas não sementes. Esses dois grupos se reproduzem por ciclos que incluem esporos.

Gimnospermas, como pinheiros, possuem sementes que não ficam dentro de frutos. Angiospermas produzem flores e frutos; o fruto envolve as sementes. Uma mangueira com flores e mangas é exemplo de angiosperma.

Exemplo de comparação: musgo sem vasos verdadeiros é briófita; samambaia com vasos e sem sementes é pteridófita; pinheiro com sementes sem frutos é gimnosperma; feijoeiro com flores e vagens é angiosperma.

Limite: tamanho e cor não bastam para classificar. Uma angiosperma pode estar sem flores na época observada; ausência momentânea de flor não comprova outro grupo. Registre as características e o que ainda falta verificar.',question_id='00000000-0000-4000-8000-000000021025' where id='00000000-0000-4000-8000-000000003061';
update public.modules set title='Observação científica',body='Observar cientificamente é registrar características que podem ser verificadas. Separe observação, como ver uma folha verde, de interpretação, como explicar a função daquela folha.

Órgãos vegetais possuem funções: a raiz absorve água e sais e ajuda na fixação; o caule sustenta e transporta substâncias; a folha costuma ser o principal órgão fotossintetizante; a flor participa da reprodução das angiospermas.

Exemplo de registro: em uma planta no vaso, vejo caule, quatro folhas e uma flor. Não vejo a raiz porque está coberta. A frase ‘a raiz absorve água’ é uma explicação de função, não uma observação direta dessa raiz.

Anote data, local, partes visíveis e uma descrição sem arrancar a planta. Um desenho rotulado ou uma foto autorizada pode ajudar a repetir a observação. Se comparar dias, mantenha ponto de vista e condições semelhantes.

Limite: não ver uma estrutura não prova que ela não existe. Não invente cor ou tamanho de uma raiz oculta. Diferencie o que foi visto, a função conhecida do órgão e uma hipótese que precisaria de outra observação.',question_id='00000000-0000-4000-8000-000000021029' where id='00000000-0000-4000-8000-000000003062';
update public.modules set title='Identificar estruturas celulares',body='Um esquema celular representa estruturas para facilitar a comparação de posições e funções. Neste desenho de célula eucariótica, procure primeiro o limite externo, depois a estrutura central e a região interna ao redor dela.

A membrana delimita a célula e regula trocas. O núcleo abriga a maior parte do material genético. O citoplasma é a região interna entre a membrana e o núcleo, onde ficam diversas estruturas celulares.

No esquema da prática, 1 indica a membrana, 2 indica o núcleo e 3 indica o citoplasma. Siga cada linha até a estrutura: o número 2 está à direita, mas sua linha termina na estrutura arredondada central.

Exemplo: se a pergunta pede o núcleo, escolha 2 porque a linha aponta para a estrutura central delimitada. Se pede o contorno externo, escolha 1. A região ao redor do núcleo corresponde a 3, citoplasma.

Limite: a posição do número no papel não é a posição da estrutura. Cores e proporções são escolhas didáticas; não representam todas as células nem todas as organelas. Use a ponta da linha e a função para conferir.',question_id='00000000-0000-4000-8000-000000021032' where id='00000000-0000-4000-8000-000000004015';
update public.modules set title='Classificar grupos de plantas',body='Uma classificação precisa de um critério verificável. Para estes grupos, compare vasos condutores, presença de sementes e presença de frutos; não use apenas o tamanho ou o ambiente da planta.

Briófitas não possuem vasos condutores verdadeiros. Pteridófitas possuem vasos, mas não sementes. Gimnospermas têm sementes sem frutos. Angiospermas possuem flores e frutos que envolvem sementes.

Exemplo: a amostra A tem sementes em cones, sem frutos, e corresponde a uma gimnosperma. A amostra B tem flores e frutos com sementes, correspondendo a uma angiosperma. Vasos, sozinhos, não distinguem esses dois grupos.

Organize uma decisão: sem vasos verdadeiros, considere briófitas; com vasos e sem sementes, pteridófitas; com sementes, investigue frutos. Confira mais de uma característica e registre qual evidência sustenta cada associação.

Limite: uma amostra incompleta pode não mostrar semente ou fruto existente em outra época. Escreva ‘dados insuficientes’ quando necessário. Não transforme a falta de uma observação em prova de ausência no grupo.',question_id='00000000-0000-4000-8000-000000021036' where id='00000000-0000-4000-8000-000000004016';
update public.modules set title='Grandezas e unidades',body='Grandeza física é uma propriedade que pode ser medida, como comprimento, tempo ou massa. Uma medida combina valor e unidade: 2 m indica dois metros, enquanto 2 s indica dois segundos.

No Sistema Internacional, comprimento usa metro (m), tempo usa segundo (s) e massa usa quilograma (kg). Massa expressa uma propriedade do corpo; peso é a força gravitacional sobre ele, medida em newtons (N).

Força descreve uma interação capaz de alterar o movimento ou deformar um corpo e usa newton (N). Energia está associada à capacidade de realizar trabalho ou provocar transformações e usa joule (J). Potência é a energia transferida por tempo e usa watt (W).

Exemplo: registre comprimento de uma mesa como 2 m, duração como 10 s, massa de um pacote como 3 kg, força como 20 N, energia como 100 J e potência como 5 W. Cada unidade identifica uma grandeza diferente.

Limite: o número isolado não basta. ‘O pacote mede 3’ não informa se são metros ou quilogramas. Não troque kg por N nem J por W; comparar valores exige a mesma grandeza e unidades compatíveis.',question_id='00000000-0000-4000-8000-000000021040' where id='00000000-0000-4000-8000-000000003070';
update public.modules set title='Movimento',body='Movimento é a mudança de posição em relação a um referencial, como uma marca no chão. Distância é o comprimento total do caminho percorrido; tempo é a duração observada. Registre distância em metros e tempo em segundos.

Rapidez média é a distância total dividida pelo tempo total: rapidez = distância / tempo. A unidade m/s significa quantos metros por segundo correspondem à média do trajeto, sem afirmar que o ritmo foi constante.

Exemplo: uma pessoa caminha 10 m em 5 s. Dividindo 10 por 5, a rapidez média é 2 m/s. Se percorrer os mesmos 10 m em 10 s, a média será 1 m/s, menor porque levou mais tempo.

Distância e deslocamento são diferentes: ao andar 5 m e voltar 5 m ao início, a distância é 10 m e o deslocamento total é zero. A velocidade média usa deslocamento e direção; a rapidez média usa distância.

Limite: tempo total precisa ser maior que zero para dividir. Inclua uma parada se ela pertence ao intervalo observado. Uma média de 2 m/s não permite concluir que a pessoa manteve 2 m/s a cada instante.',question_id='00000000-0000-4000-8000-000000021043' where id='00000000-0000-4000-8000-000000003071';
update public.modules set title='Medição e análise',body='Medir é comparar uma grandeza com uma unidade usando um instrumento. Para estudar movimento, defina o trecho, meça sua distância e registre o intervalo de tempo com o mesmo critério de início e fim.

Uma fita métrica pode medir distância; um cronômetro registra duração. Anote valor e unidade de cada leitura. Rapidez média usa distância por tempo; velocidade média usa deslocamento por tempo e exige considerar direção.

Exemplo em linha reta sem retorno: entre duas marcas há 12 m e o tempo é 6 s. A rapidez média é 12 / 6 = 2 m/s. Nesse percurso, a distância e o módulo do deslocamento coincidem.

Planeje medições repetidas do mesmo trecho, mantendo o critério. Tempos de 6,0 s e 6,2 s podem diferir por reação ao cronômetro ou variação de movimento; registre as duas leituras em vez de apagar a que não esperava.

Limite: um cálculo não elimina incerteza de medição. Escolha um trajeto seguro para caminhada ou trabalhe com dados hipotéticos. Não faça teste em via com tráfego; não conclua a precisão do instrumento apenas pelo número de casas decimais anotado.',question_id='00000000-0000-4000-8000-000000021048' where id='00000000-0000-4000-8000-000000003072';
update public.modules set title='Calcular rapidez média',body='Rapidez média é a distância total percorrida dividida pelo tempo total observado. Ela resume um trajeto em um único valor e não informa a direção; velocidade média usa o deslocamento, que pode ser diferente da distância.

Em um trajeto por etapas, some primeiro todas as distâncias e todos os tempos. Inclua intervalos de parada que façam parte da observação. Só depois divida a distância total pelo tempo total, com unidades compatíveis.

Exemplo: uma pessoa percorre 120 m em 60 s e mais 60 m em 30 s. A distância total é 120 + 60 = 180 m e o tempo total é 60 + 30 = 90 s. Logo, 180 m / 90 s = 2 m/s.

Confira com outra situação: 10 m em 10 s e 90 m em 30 s totalizam 100 m em 40 s, ou 2,5 m/s. Fazer a média simples de 1 m/s e 3 m/s daria 2 m/s e estaria errado, pois as durações são diferentes.

Limite: não divida por tempo zero nem some metros com quilômetros sem converter. Se a pessoa retorna ao ponto inicial, o deslocamento é zero, mas a distância e a rapidez podem ser positivas. A média não comprova ritmo constante.',question_id='00000000-0000-4000-8000-000000021052' where id='00000000-0000-4000-8000-000000004017';
update public.modules set title='Interpretar uma medição',body='Interpretar uma medição é reconhecer a grandeza, a unidade e o que o registro permite concluir. Valores numéricos diferentes podem representar a mesma quantidade quando as unidades mudam.

Um quilômetro corresponde a 1000 metros. Para passar de km para m, multiplique por 1000; para passar de m para km, divida por 1000. Um minuto corresponde a 60 segundos, portanto a conversão de tempo usa outro fator.

Exemplo: 1,5 km × 1000 = 1500 m. Os registros 1,5 km e 1500 m representam a mesma distância. Para comparar com 1200 m, use a mesma unidade: 1500 m é 300 m maior que 1200 m.

Antes de calcular rapidez, converta também o tempo: 0,12 km são 120 m e 1 min são 60 s. Assim, 120 m / 60 s = 2 m/s. Registre as conversões para outra pessoa poder conferir a conta.

Limite: escrever 1500 m em vez de 1,5 km não comprova maior precisão. Precisão depende do instrumento, do procedimento e da repetição; a escrita sozinha não basta. Não compare distância com tempo como se fossem a mesma grandeza.',question_id='00000000-0000-4000-8000-000000021056' where id='00000000-0000-4000-8000-000000004018';
